//! 🗂️ The neutral map matrix exercises real original key indexing, typed row receiving and cancellation custody.
use semio_framework_value::{paged::PagedMap,NativeDecodeControl,RetirementDemand,RetainedCloneGrant};
use semio_framework_value_native_owned::native_decoding::{NativeReceive,NativeReceiver,owned::tree::NativeValueSource};
use semio_framework_value_testing_allocator as _;
use semio_framework_value::{DslValue,retained_clone::RetainedCloneSource};
use super::{Wallet,original,drain};
#[test]fn original_map_keys_receive_in_authored_order_and_reject_duplicates(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let names:std::collections::BTreeSet<_>=row["entries"].as_array().unwrap().iter().map(|pair|pair[0].as_str().unwrap()).collect();assert_eq!(names.len()==row["entries"].as_array().unwrap().len(),row["accepted"].as_bool().unwrap());for cut in [0,1,5,30,4096]{let entries=row["entries"].as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_string(),DslValue::from(pair[1].clone()))).collect();let mut wallet=Wallet::new();let source=original(DslValue::Object(entries),&mut wallet);let mut receiver=<PagedMap<u32,4096> as NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut rejected=false;for _ in 0..cut{if receiver.output_ready(){break}let d=receiver.demands(source.borrow(),4096).unwrap();let g=wallet.grant();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(source.borrow(),4096).unwrap(),d);}let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,g));let p=result.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,result.work);match result.result{Ok(step)=>{let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));},Err(error)=>{let p=error.retained_progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));rejected=true;break}}}if cut==4096{assert_eq!(!rejected,row["accepted"].as_bool().unwrap());if !rejected{assert!(receiver.output_ready())}}if receiver.output_ready(){let turn=receiver.take(wallet.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();wallet.debit(p,turn.work);let(output,_)=turn.result.unwrap().unwrap();assert_eq!(output.len(),row["entries"].as_array().unwrap().len());for(index,(key,value))in output.iter().enumerate(){assert_eq!(key.to_string_owner(),row["entries"][index][0].as_str().unwrap());assert_eq!(*value,row["entries"][index][1].as_u64().unwrap()as u32)}drain(output,&mut wallet);}receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let turn=receiver.close_step(wallet.grant());let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,turn.work);turn.result.unwrap();}assert!(receiver.terminal_is_empty());drain(source,&mut wallet);}}}

#[test]
fn shared_original_paged_map_supports_erased_receiving_and_funded_default(){
 use semio_framework_value_native_owned::native_decoding::owned::{NativeDefault,NativeDefaultCursor};
 fn supported<T:Sync+NativeReceive<dyn NativeValueSource>+NativeDefault>(){}
 supported::<PagedMap<u32,4096>>();
 let mut wallet=Wallet::new();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut cursor=<PagedMap<u32,4096> as NativeDefault>::default_cursor();
 for _ in 0..10000{if cursor.output_ready(){break}let turn=cursor.advance(&mut control,4096,wallet.grant());let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,turn.work);turn.result.unwrap();}assert!(cursor.output_ready());
 let turn=cursor.take(wallet.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();wallet.debit(p,turn.work);let(map,_)=turn.result.unwrap().unwrap();assert_eq!(map.len(),0);drain(map,&mut wallet);cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){break}let turn=cursor.close_step(wallet.grant());let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,turn.work);turn.result.unwrap();}assert!(cursor.terminal_is_empty());
}
